sys_script.script:
(function executeRule(current, previous) {
    var feederId = current.getValue('feeder');
    var startAreaId = current.getValue('start_area');
    var endAreaId = current.getValue('end_area');

    // Feeder must be populated
    if (!feederId) {
        gs.addErrorMessage('Feeder is required for a Distribution Line.');
        current.setAbortAction(true);
        return;
    }

    // For new records, feeder must be active
    if (current.isNewRecord()) {
        var feederGr = new GlideRecord('x_1966159_utilit_0_feeder');
        if (feederGr.get(feederId)) {
            if (feederGr.getValue('active') != '1' && feederGr.getValue('active') != 'true') {
                gs.addErrorMessage('Distribution Line must reference an active Feeder.');
                current.setAbortAction(true);
                return;
            }
        }
    }

    // Start Area must be populated
    if (!startAreaId) {
        gs.addErrorMessage('Start Area is required for a Distribution Line.');
        current.setAbortAction(true);
        return;
    }

    // End Area must be populated
    if (!endAreaId) {
        gs.addErrorMessage('End Area is required for a Distribution Line.');
        current.setAbortAction(true);
        return;
    }

    // Start and End areas must be different
    if (startAreaId === endAreaId) {
        gs.addErrorMessage('Start Area and End Area must be different.');
        current.setAbortAction(true);
        return;
    }

    // Both areas must be Village or Street (not City)
    var startGr = new GlideRecord('x_1966159_utilit_0_area');
    if (startGr.get(startAreaId)) {
        var startType = startGr.getValue('area_type');
        if (startType === 'city') {
            gs.addErrorMessage('Start Area cannot be a City. Only Village or Street areas are allowed.');
            current.setAbortAction(true);
            return;
        }
    }

    var endGr = new GlideRecord('x_1966159_utilit_0_area');
    if (endGr.get(endAreaId)) {
        var endType = endGr.getValue('area_type');
        if (endType === 'city') {
            gs.addErrorMessage('End Area cannot be a City. Only Village or Street areas are allowed.');
            current.setAbortAction(true);
            return;
        }
    }
})(current, previous);
